  interativos: [
    {"x": 22, "y": 29, "id": "plataformaDaAnima", "rotulo": "Olhar a plataforma", "texto": "Uma plataforma de pedra presa à borda da bacia, com uma escada larga que sobe entre tentáculos que ondulam devagar. Das arcadas pendem correntes com globos violeta acesos."},
    {"x": 23, "y": 15, "id": "covaDaAnima", "rotulo": "Olhar a cova", "texto": "Uma cova rasa e redonda, cheia de névoa. Dentro dela, pequena como um brinquedo, está Phandalin: as casas tortas aparecem e somem, e da névoa sobem gritos com vozes que vocês conhecem."},
    {"x": 38, "y": 14, "id": "tubosDaAnima", "rotulo": "Olhar os tubos", "texto": "Três tubos de metal da grossura de um braço descem do teto, pingando um líquido roxo e grosso. Têm uma boca na ponta, à altura da mão."},
    {"x": 37, "y": 20, "id": "prateleiraDaAnima", "rotulo": "Olhar a prateleira", "texto": "Uma prateleira torta presa à parede de tentáculos, com potes de carne e um frasco que brilha vermelho por dentro."},
    {"x": 8, "y": 13, "id": "lajesDaAnima", "rotulo": "Olhar as lajes", "texto": "Seis lajes de pedra saem da parede como camas, ou bancos. Estão limpas e nunca foram usadas: esperam gente que ainda não chegou."},
    {"x": 15, "y": 15, "id": "altarDaAnima", "rotulo": "Olhar o altar", "texto": "Um altar com uma estátua de um cérebro humanoide da altura de um homem, cravejada de diamantes. Sobre o altar, tabuletas de pedra cobertas de escrita."},
    {"x": 22, "y": 8, "id": "obeliscoDaAnima", "rotulo": "Olhar o obelisco", "texto": "Num estrado, um obelisco negro remendado, com costuras de energia verde viva correndo entre os pedaços. Onde falta pedaço, a costura fecha o buraco do mesmo jeito."},
  ],
